# Daily observations use REFERENCE rows so raw validity remains pure-library
# mathematics. Legacy DAILY/BAR zero-volume admission is deliberately unchanged.
_DAILY_COLUMNS = frozenset(("instrument_id", "session_id", "reference_id", "fact_kind",
                            "effective_start_ns", "effective_end_ns", "text", "known_at_ns"))


def make_daily_observations_batch(column_order: tuple[str, ...],
                                  rows: tuple[tuple[Cell, ...], ...], *,
                                  metadata: BatchMetadata) -> CanonicalBatch:
    """Convert supplied rectangular REF rows without sorting or manufacturing facts.

    Text is the caller's original canonical JSON, never reserialized here. Original
    knowledge (including null), IDs, units, metadata and row/column order survive.
    Closed daily grammar, calendar joins and all admission mathematics belong to
    the pure producer. This converter authenticates neither source nor rights.
    """
    if (type(column_order) is not tuple or any(type(name) is not str for name in column_order)
            or len(column_order) != 8 or frozenset(column_order) != _DAILY_COLUMNS
            or type(rows) is not tuple
            or any(type(row) is not tuple or len(row) != len(column_order) for row in rows)):
        raise ContractError(ErrorCode.INVALID_SCHEMA, "Exact supplied daily REFERENCE schema required")
    batch = CanonicalBatch(DataKind.REFERENCE,
        tuple(Column(name, tuple(row[i] for row in rows)) for i, name in enumerate(column_order)), metadata)
    validate_batch(batch, required_fields=())
    return batch


@dataclass(frozen=True)
class DailyObservationsInputs:
    """Six nullable logical roles; only present actual batches enter generic tasks.

    Provenance is explicit per slot: synthetic, duckdb_backed_observed or
    unavailable. Declaring an observed origin does not qualify the source.
    """
    calendar_manifest: CanonicalBatch | None = None
    calendar_slots: CanonicalBatch | None = None
    observation_coverage: CanonicalBatch | None = None
    raw_observations: CanonicalBatch | None = None
    common_observations: CanonicalBatch | None = None
    basis_provenance: CanonicalBatch | None = None
    provenance: tuple[str, ...] = ("unavailable",) * 6

    def __post_init__(self) -> None:
        _validate_observable_slots(self.roles, self.slots, self.provenance)
        for batch in self.batches:
            if len(batch.columns) != 8 or frozenset(c.name for c in batch.columns) != _DAILY_COLUMNS:
                raise ContractError(ErrorCode.INVALID_SCHEMA, "Exact supplied daily REFERENCE schema required")

    @property
    def roles(self) -> tuple[str, ...]:
        return ("calendar_manifest", "calendar_slots", "observation_coverage",
                "raw_observations", "common_observations", "basis_provenance")

    @property
    def slots(self) -> tuple[CanonicalBatch | None, ...]:
        return (self.calendar_manifest, self.calendar_slots, self.observation_coverage,
                self.raw_observations, self.common_observations, self.basis_provenance)

    @property
    def batches(self) -> tuple[CanonicalBatch, ...]:
        return tuple(batch for batch in self.slots if batch is not None)


__all__ += ["DailyObservationsInputs", "make_daily_observations_batch"]


