def _synthetic_daily_packet(case_id: str) -> dict[str, object]:
    packets = cast(dict[str, dict[str, object]], json.loads(_SYNTHETIC_DAILY_PACKETS))
    if type(case_id) is not str or case_id not in packets:
        raise ContractError(ErrorCode.INVALID_CONFIG, "Unknown original synthetic daily example")
    return packets[case_id]


def synthetic_daily_observations_config(case_id: str = "V235-literal-last252") -> ConfigSpec:
    """Literal supplied config; never derives calendar facts or admission policy."""
    return ConfigSpec.from_json(json.dumps(_synthetic_daily_packet(case_id)["config"],
        ensure_ascii=True, sort_keys=True, separators=(",", ":"), allow_nan=False))


def synthetic_daily_observations_fixture(case_id: str = "V235-literal-last252") -> DailyObservationsInputs:
    """Literal supplied role packets for three original synthetic public examples.

    All proofs and known-at operands are explicit synthetic assertions. No N-drive
    extraction, original source parity or calendar/rights qualification is implied.
    """
    entries = cast(list[dict[str, object]], _synthetic_daily_packet(case_id)["role_slots"])
    slots: list[CanonicalBatch | None] = []
    for entry in entries:
        b = cast(dict[str, object] | None, entry["batch"])
        if b is None:
            slots.append(None)
            continue
        m = cast(dict[str, object], b["metadata"])
        # This closed literal has no interval-coverage declarations or optional
        # outer price/factor fields; every supplied metadata value is retained.
        coverage = cast(dict[str, object], m["coverage"])
        unit = cast(dict[str, object] | None, m["price_unit"])
        scope = cast(dict[str, object] | None, m["scope"])
        metadata = BatchMetadata(
            namespace=cast(str, m["namespace"]),
            source=SourceBinding(**cast(dict[str, str], m["source"])),
            coverage=Coverage(cast(int | None, coverage["expected"]), cast(int, coverage["observed"]), cast(bool, coverage["complete"])),
            price_unit=None if unit is None else PriceUnit(cast(int, unit["scale"]), cast(str, unit["currency"])),
            adjustment=AdjustmentSpec(**cast(dict[str, str], m["adjustment"])),
            sampling=cast(str, m["sampling"]), quantity_unit=cast(str, m["quantity_unit"]),
            ordering=cast(str, m["ordering"]), duplicate_policy=cast(str, m["duplicate_policy"]),
            scope=None if scope is None else InputScope(cast(int, scope["start_ns"]), cast(int, scope["end_ns"]), cast(str, scope["eligibility_policy"]), cast(bool, scope["include_opening_auction"]), cast(bool, scope["include_closing_auction"])),
            interval_coverage=())
        columns = cast(list[dict[str, object]], b["columns"])
        names = tuple(cast(str, c["name"]) for c in columns)
        values = tuple(cast(list[Cell], c["values"]) for c in columns)
        slots.append(make_daily_observations_batch(names, tuple(zip(*values)), metadata=metadata))
    return DailyObservationsInputs(slots[0], slots[1], slots[2], slots[3], slots[4], slots[5],
        tuple("unavailable" if batch is None else "synthetic" for batch in slots))


